   640	// 校验上游响应体是否「干净可缓存」：挡掉 success:false / errorCode!=0 / 空结果。
   641	// 仅缓存真正有数据的成功响应，避免空响应/限流/错误污染缓存。
   642	function isCacheableResponseBody(apiPath, responseText) {
   643	    if (!responseText) return false;
   644	    let data;
   645	    try {
   646	        data = JSON.parse(responseText);
   647	    } catch (_) {
   648	        return false; // 非 JSON 不缓存
   649	    }
   650	    if (!data || typeof data !== 'object') return false;
   651	    // dandanplay 统一约定：success=false 或 errorCode 非 0 即失败响应
   652	    if (data.success === false) return false;
   653	    if (typeof data.errorCode === 'number' && data.errorCode !== 0) return false;
   654	    // 按接口校验是否含实际数据，空结果不缓存
   655	    if (apiPath.startsWith('/api/v2/search/anime') || apiPath.startsWith('/api/v2/search/episodes')) {
   656	        return Array.isArray(data.animes) && data.animes.length > 0;
   657	    }
   658	    if (apiPath.startsWith('/api/v2/bangumi/')) {
