   660	        return !!(bangumi && (bangumi.animeId || bangumi.animeTitle));
   661	    }
   662	    if (apiPath.startsWith('/api/v2/match')) {
   663	        return Array.isArray(data.matches) && data.matches.length > 0;
   664	    }
   665	    // 其他接口：只要不是失败响应即可缓存
   666	    return true;
