   669	// 判断是否为「真实空搜索结果」：200、success 非 false、errorCode==0，但 animes 为空。
   670	// 仅 search/anime、search/episodes 适用；明确排除 429/失败响应。
   671	function isTrueEmptySearch(apiPath, responseText) {
