   673	    if (!responseText) return false;
   674	    let data;
   675	    try { data = JSON.parse(responseText); } catch (_) { return false; }
   676	    if (!data || typeof data !== 'object') return false;
   677	    if (data.success === false) return false;
   678	    if (typeof data.errorCode === 'number' && data.errorCode !== 0) return false;
