   682	// 裸系列词若被上游模糊搜索成唯一的第二季及以上条目，按空结果处理。
   683	// 明确带季号的搜索、多季度结果和普通精确标题均保持原响应。
   684	function suppressMisleadingBareSeries(apiPath, targetUrl, responseText) {
