   691	    const title = normalizeSearchKeyword(data.animes[0]?.animeTitle || '');
   692	    const chinese = title.match(/^(.*?)\s*第\s*([二三四五六七八九十0-9]+)\s*季(?:\s.*)?$/i);
   693	    const roman = title.match(/^(.*?)\s+(viii|vii|iii|vi|iv|ii|ix|x|v)$/i);
