   697	    const romans = { ii: 2, iii: 3, iv: 4, v: 5, vi: 6, vii: 7, viii: 8, ix: 9, x: 10 };
   698	    const seasonMark = String(match[2] || '').toLowerCase();
   699	    const season = Number(seasonMark) || cn[seasonMark] || romans[seasonMark] || 0;
