   713	        }
   714	        if (m.size > EMPTY_CACHE_CONFIG.MAX_COUNTERS) m.clear();
   715	    }
   716	    let rec = m.get(normKey);
   717	    if (!rec || now - rec.firstAt > EMPTY_CACHE_CONFIG.COUNTER_WINDOW_MS) {
   718	        rec = { count: 0, firstAt: now };
   719	    }
   720	    rec.count++;
   721	    m.set(normKey, rec);
   722	    return rec.count >= EMPTY_CACHE_CONFIG.THRESHOLD;
