   725	// 构造标准化 cache key：METHOD:PATH?sorted_query（剔除 _t/timestamp）
   726	function buildLocalCacheKey(method, apiPath, searchParams) {
   727	    const sorted = [...searchParams.entries()]
   728	        .filter(([k]) => !['_t', 'timestamp'].includes(k))
   729	        .sort(([a], [b]) => a.localeCompare(b))
   730	        .map(([k, v]) => `${k}=${v}`)
