   738	function extractEpisodeFromSeason(responseText, epNo) {
   739	    if (!responseText || !epNo) return null;
   740	    let data;
   741	    try {
   742	        data = JSON.parse(responseText);
   743	    } catch (_) {
   744	        return null;
   745	    }
   746	    if (!data || !Array.isArray(data.animes)) return null;
   747	
   748	    const want = String(epNo).trim();
   749	    const wantNum = Number(want);
   750	    // 多季场景：animes 每项各带自己的 episodes，需逐项过滤后保留命中的项，
   751	    // 与本地端 entity_assemble 的 _assemble_episodes 行为保持一致
   752	    const picked = [];
   753	    for (const anime of data.animes) {
   754	        if (!anime || !Array.isArray(anime.episodes)) continue;
   755	        const animeId = String(anime.animeId || '');
   756	        const hit = anime.episodes.filter(ep => {
   757	            if (!ep) return false;
   758	            // 上游集号字段形态不统一：episodeNumber 优先，缺失则从 episodeTitle 里取「第N话」
   759	            let n = ep.episodeNumber;
   760	            if (n === undefined || n === null || n === '') {
   761	                const m = /第\s*(\d+)\s*[话集]/.exec(ep.episodeTitle || '');
   762	                n = m ? m[1] : null;
   763	            }
   764	            // 末级兜底：从 episodeId 剥掉 animeId 前缀得集号（97710007 - 9771 → 0007 → 7）。
   765	            // 与本地端 entity_service._episode_entity 同策略：必须校验前缀匹配，
