   823	                memoryCache.doMonitor.toolCalls[operation] = target;
   824	            }
   825	            memoryCache.doMonitor.pendingRpc = Number(incoming.pendingRpc || 0);
   826	            memoryCache.doMonitor.websocketConnections = Number(incoming.websocketConnections || 0);
   827	        } catch (_) { /* 监控头异常不影响配置拉取 */ }
   828	        const cfg = await resp.json();
   829	        applyRuntimeConfig(cfg);
