  1111	        return;
  1112	    }
  1113	    const now = Date.now();
  1114	    let totalSize = 0;
  1115	    let liveObjects = [];
  1116	    let expiredKeys = [];
  1117	    let cursor = undefined;
  1118	    let listCount = 0;
