  1168	
  1169	    // 阈值清理后再次校准估算值
  1170	    memoryCache.r2EstimatedBytes = totalSize - freedSize;
  1171	    console.log(`🔄 R2 估算值已校准（阈值清理后）: ${((totalSize - freedSize) / 1024 / 1024).toFixed(1)} MB`);
  1172	}
