function pruneMergeWorkerQueue() {
    for (let i = _mergeWorkerQueue.length - 1; i >= 0; i--) {
        if (!_mergeWorkerQueue[i].isCurrent()) {
            // 过期任务也必须结束 Promise，让上层会话检查正常退出。
            _mergeWorkerQueue.splice(i, 1)[0].resolve([]);
        }
    }
}

