namespace DD.Danmaku.Hosting;

using System.Globalization;
using System.Text.Json;
using DD.Danmaku.Danmaku;
using MediaBrowser.Controller.Entities;

public sealed partial class DanmakuApiService
{
    // 中转已取得正文时直接写文件，不要求浏览器再次上传；失败状态附加在 JSON 中。
    private async Task<byte[]> SaveProxyCommentsAsync(byte[] body, string? itemId, string source,
        string episodeId, User user, Plugin plugin, EmbyHostServices host)
    {
        var status = "skipped";
        var code = "NO_MEDIA_CONTEXT";
        try
        {
            if (!string.IsNullOrWhiteSpace(itemId))
            {
                var id = _access.RequireVideo(user, itemId);
                var c = plugin.Configuration;
                if (!c.FilePersistenceEnabled || !c.FilePersistenceWriteEnabled || !c.AutoSaveDanmaku
                    || !user.Policy.IsAdministrator)
                    code = "AUTO_SAVE_DISABLED";
                else
                {
                    using var json = JsonDocument.Parse(body);
                    var root = json.RootElement;
                    if (root.TryGetProperty("success", out var success) && success.ValueKind == JsonValueKind.False)
                        throw new InvalidDataException("上游未成功返回弹幕");
                    if (!root.TryGetProperty("comments", out var array) || array.ValueKind != JsonValueKind.Array)
                        throw new InvalidDataException("上游弹幕正文缺失");
                    if (array.GetArrayLength() > DanmakuXml.MaxComments) throw new InvalidDataException("弹幕条数超过限制");
                    var comments = new List<DanmakuComment>();
                    foreach (var entry in array.EnumerateArray())
                    {
                        var fields = entry.GetProperty("p").GetString()?.Split(',') ?? [];
                        if (fields.Length < 3) throw new InvalidDataException("上游弹幕字段无效");
                        var text = entry.GetProperty("m").GetString() ?? "";
                        var cid = entry.TryGetProperty("cid", out var value) ? value.ToString() : null;
                        var comment = new DanmakuComment(text,
                            double.Parse(fields[0], CultureInfo.InvariantCulture),
                            int.Parse(fields[1], CultureInfo.InvariantCulture),
                            int.Parse(fields[2], CultureInfo.InvariantCulture), fields.Length > 3 ? fields[3] : null,
                            Cid: cid);
                        DanmakuXml.Validate(comment);
                        comments.Add(comment);
                    }
                    if (comments.Count == 0) code = "EMPTY_COMMENTS";
                    else
                    {
                        await host.Playback.SaveAsync(id, comments, Request.CancellationToken, false, source,
                            new DanmakuXmlMetadata { SourceEpisodeId = episodeId,
                                UpdatedByUserId = user.Id.ToString("N"), WriteMethod = "auto",
                                FetchedAt = DateTimeOffset.UtcNow });
                        status = "saved";
                        code = "SAVED";
                    }
                }
            }
        }
        catch (OperationCanceledException) { throw; }
        catch (ApiAccessException error) { status = error.Code == "XML_EXISTS" ? "skipped" : "failed"; code = error.Code; }
        catch (Exception error) when (error is IOException or UnauthorizedAccessException or JsonException
            or InvalidDataException or FormatException or OverflowException or ArgumentException
            or InvalidOperationException or KeyNotFoundException)
        { status = "failed"; code = "AUTO_SAVE_FAILED"; }
        // 不改变上游字段协议，保存失败也返回已取得的弹幕供播放器使用。
        using var document = JsonDocument.Parse(body);
        using var output = new MemoryStream();
        using (var writer = new Utf8JsonWriter(output))
        {
            writer.WriteStartObject();
            foreach (var property in document.RootElement.EnumerateObject())
                if (property.Name != "ddSave") property.WriteTo(writer);
            writer.WritePropertyName("ddSave");
            JsonSerializer.Serialize(writer, new { status, code });
            writer.WriteEndObject();
        }
        return output.ToArray();
    }
}

