            const response = await fetch(`${base}/dd-danmaku/api/items/${encodeURIComponent(itemId)}/selection`, {
                method: 'DELETE', headers: { 'X-Emby-Token': token }
            });
            if (!response.ok) throw new Error(response.status === 403 ? '未获得临时选择操作权限' : '恢复共享失败');
            if (key !== manualDanmakuKey(window.ede?.itemId)) return;
            manualDanmakuSelection = null;
            embyToast({ text: '已恢复共享弹幕' });
            await loadDanmaku(LOAD_TYPE.REFRESH);
        } catch (error) { embyToast({ text: error.message || '恢复共享失败' }); }
        finally { restore.disabled = false; }
    });
}

namespace DD.Danmaku.Hosting;

using DD.Danmaku.Danmaku;

internal sealed partial class LocalPlaybackService
{
    /// <summary>共享刷新在同一文件锁内读取绑定、取回、覆盖，避免并发重复刷新或覆盖新上传。</summary>
    internal async Task<string?> RefreshSharedAsync(string id, string? source, int freshHours,
        Action authorize, Func<DanmakuXmlMetadata, Task<IReadOnlyList<DanmakuComment>>> fetch,
        string actor, CancellationToken token)
    {
        await _gate.WaitAsync(token);
        try
        {
            var path = await RequirePathAsync(id, token, source);
            DanmakuXmlReadReport report;
            try
            {
                await using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read);
                report = await DanmakuXml.ReadReportAsync(stream, token);
            }
            catch (FileNotFoundException) { return null; }
            catch (DirectoryNotFoundException) { return null; }
            var metadata = report.Metadata;
            if (metadata is null || string.IsNullOrEmpty(metadata.SourceId)
                || string.IsNullOrEmpty(metadata.SourceEpisodeId)) return "SHARED_BINDING_UNKNOWN";
            if (metadata.EmbyItemId != id || metadata.SourceId != NormalizeSource(source))
                return "SHARED_BINDING_MISMATCH";
            var now = DateTimeOffset.UtcNow;
            if (metadata.FetchedAt is { } fetched && fetched <= now
                && now - fetched < TimeSpan.FromHours(freshHours)) return null;
            authorize();
            var comments = await fetch(metadata);
            authorize();
            // 获取时间只在成功取得新正文时更新，失败不删除旧文件。
            var updated = metadata with { FetchedAt = DateTimeOffset.UtcNow,
                UpdatedByUserId = actor, WriteMethod = "refresh" };
            await _files.SaveWithMetadataAsync(path, comments, token, true, updated, authorize);
            await records.MutateAsync(items =>
            {
                var index = items.FindIndex(x => x.ItemId == id
                    && JsonDanmakuRecordStore.GetEffectiveSource(x) == NormalizeSource(source));
                if (index >= 0) items[index] = items[index] with { CommentCount = comments.Count,
                    FetchedAt = updated.FetchedAt, UpdatedAt = DateTimeOffset.UtcNow,
                    UpdatedByUserId = actor, WriteMethod = "refresh", RefreshState = "fresh" };
            }, token);
            return null;
        }
        finally { _gate.Release(); }
    }
}

namespace DD.Danmaku.Hosting;

using System.Net.Http;
using System.Text.Json;
using DD.Danmaku.Danmaku;
using DD.Danmaku.Web.Api;
using MediaBrowser.Controller.Entities;

public sealed partial class DanmakuApiService
{
    private async Task<PlaybackQueryDto> QuerySharedPlaybackAsync(string id, string? source,
        User user, Plugin plugin, EmbyHostServices host)
    {
        var token = Request.CancellationToken;
        // 先读取旧正文，任何刷新失败都不影响已可用的共享弹幕。
        var old = await host.Playback.QueryAsync(id, token, source);
        if (!old.Found) return old;
        string? reason;
        var config = plugin.Configuration;
        void Authorize()
        {
            var current = _access.Authenticate(Request);
            if (current.Id != user.Id) throw new ApiAccessException(403, "USER_CHANGED", "用户身份已变化");
            _access.RequireVideo(current, id);
            DanmakuWritePolicy.Require(current, plugin.Configuration, DanmakuWritePolicy.Operation.RefreshShared);
            var actualSource = source ?? "";
            if (SelectionUpstreamRevision(actualSource, config) != SelectionUpstreamRevision(actualSource, plugin.Configuration))
                throw new ApiAccessException(409, "UPSTREAM_CHANGED", "弹幕上游配置已变化");
        }
        try
        {
            reason = await host.Playback.RefreshSharedAsync(id, source, config.SharedDanmakuFreshHours, Authorize,
                metadata => FetchSelectionCommentsAsync(new SelectionContentIdentity(id, metadata.SourceId!,
                    metadata.SourceEpisodeId!, 0, SelectionUpstreamRevision(metadata.SourceId!, config)),
                    user.Id, config, token), user.Id.ToString("N"), token);
            if (reason is null) return await host.Playback.QueryAsync(id, token, source);
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested) { throw; }
        catch (Exception error) when (error is ApiAccessException or IOException or UnauthorizedAccessException
            or JsonException or HttpRequestException or OperationCanceledException or InvalidOperationException
            or ArgumentException or FormatException or OverflowException or KeyNotFoundException)
        {
            reason = error is ApiAccessException access ? access.Code : "SHARED_REFRESH_FAILED";
        }
        return old with { RefreshRequired = true, RefreshReason = reason };
    }
}

