   158	            if (client?.isMinServerVersion) {
   159	                apiSaysOld = !client.isMinServerVersion("4.8.0.0");
   160	            } else {
   161	                const sv = client?.serverVersion ? client.serverVersion() : '';
   162	                const parts = sv.split('.').map(Number);
   163	                apiSaysOld = (parts[0] || 0) < 4 || ((parts[0] || 0) === 4 && (parts[1] || 0) < 8);
   164	            }
   165	        } catch(e) {
   166	            logger.warn('[容器探测] API 版本检测异常，回退到 DOM 探测:', e.message);
