   169	        // --- 第2层：DOM 实际探测 ---
   170	        const hasNewContainer = !!document.querySelector(_CONTAINER_SELECTORS.new);
   171	        const hasOldContainer = !!document.querySelector(_CONTAINER_SELECTORS.old);
   172	
   173	        // --- 第3层：交叉验证 & 自动修正 ---
   174	        let finalIsOld = apiSaysOld;
   175	        let source = 'API';
   176	
   177	        if (apiSaysOld && hasNewContainer && !hasOldContainer) {
   178	            // API 说旧版，但 DOM 里只有新版容器 → 修正为新版
   179	            finalIsOld = false;
   180	            source = 'DOM修正(API误判为旧版)';
   181	        } else if (!apiSaysOld && !hasNewContainer && hasOldContainer) {
   182	            // API 说新版，但 DOM 里只有旧版容器 → 修正为旧版
   183	            finalIsOld = true;
   184	            source = 'DOM修正(API误判为新版)';
   185	        } else if (!hasNewContainer && !hasOldContainer) {
   186	            // DOM 中两个都没找到（可能还没渲染），信任 API 结果
