   330	function checkOriginQuota(clientIP, uaConfig, apiPath) {
   331	    // 未配置或开关关闭 => 不限（旧库新列为空时行为与改动前一致）
   332	    if (!uaConfig || !uaConfig.originLimitEnabled) {
   333	        return { allowed: true, reason: 'origin_limit_disabled' };
   334	    }
   335	
   336	    const uaType = uaConfig.type || 'unknown';
   337	    const perHour = uaConfig.originMaxRequestsPerHour;
   338	    const perDay = uaConfig.originMaxRequestsPerDay;
   339	
   340	    console.log(`🌐 [${clientIP}] 回源配额检查: UA=${uaType} path=${apiPath}`);
   341	
   342	    // ① 路径级配额优先：命中某个路径模式时用它的值覆盖小时上限
   343	    let effectiveHourly = perHour;
   344	    let matchedPath = '';
   345	    const originPathLimits = uaConfig.originPathLimits;
   346	    if (Array.isArray(originPathLimits)) {
   347	        for (const pl of originPathLimits) {
   348	            const p = pl && (pl.path || pl.pathPattern);
   349	            if (p && apiPath.includes(p)) {
   350	                const v = pickLimitValue(
   351	                    pl.maxRequestsPerHour,
   352	                    pl.originMaxRequestsPerHour
   353	                );
   354	                if (v !== undefined) {
   355	                    effectiveHourly = v;
   356	                    matchedPath = p;
   357	                }
   358	                break;
   359	            }
   360	        }
   361	    }
   362	
   363	    // ② 小时窗口检查
   364	    if (effectiveHourly !== undefined && effectiveHourly !== null) {
   365	        const suffix = matchedPath ? `-path-${matchedPath}` : '';
   366	        const r = checkMemoryRateLimit(clientIP, `origin-${uaType}${suffix}`, {
   367	            windowMs: 3600000,
   368	            maxRequestsPerHour: effectiveHourly,
   369	        });
   370	        if (!r.allowed) {
   371	            return {
   372	                allowed: false,
   373	                reason: `回源配额超限(小时): ${r.count}/${r.limit}`,
   374	                count: r.count,
   375	                limit: r.limit,
   376	            };
   377	        }
   378	    }
   379	
   380	    // ③ 天窗口检查（UTC+8 自然日，与弹弹play 配额重置时区一致）
   381	    if (perDay !== undefined && perDay !== null) {
   382	        const r = checkMemoryRateLimit(clientIP, `origin-day-${uaType}`, {
   383	            windowMs: 86400000,
   384	            maxRequestsPerHour: perDay,
   385	        });
   386	        if (!r.allowed) {
   387	            return {
   388	                allowed: false,
   389	                reason: `回源配额超限(当日): ${r.count}/${r.limit}`,
   390	                count: r.count,
   391	                limit: r.limit,
   392	            };
   393	        }
   394	    }
   395	
   396	    return { allowed: true };
   397	}
