   399	/**
   400	 * 按优先级取第一个「已配置」的限流值。
   401	 *
   402	 * 存在的意义：限流值 0 是合法配置（表示无限制），但 0 在 JS 里是 falsy，
   403	 * 用 `a || b` 取值会把它当未配置而跳到兜底值上。本函数只跳过
   404	 * undefined / null，确保本地端下发的 0 能原样生效。
   405	 *
   406	 * @param {...(number|undefined|null)} values 按优先级排列的候选值
   407	 * @returns {number|undefined} 第一个非空值，全为空时返回 undefined
   408	 */
   409	function pickLimitValue(...values) {
   410	    for (const v of values) {
   411	        if (v !== undefined && v !== null) return v;
   412	    }
   413	    return undefined;
   414	}
