   416	// 内存频率限制检查
   417	function checkMemoryRateLimit(clientIP, uaType, limits) {
   418	    const now = Date.now();
   419	    const key = `${uaType}-${clientIP}`;
   420	
   421	    console.log(`🔢 频率限制检查详情:`);
   422	    console.log(`   - 限制键: ${key}`);
   423	    console.log(`   - 限制配置: ${JSON.stringify(limits)}`);
   424	
   425	    // 获取或创建计数器
   426	    if (!memoryCache.rateLimitCounts.has(key)) {
   427	        console.log(`   - 创建新计数器`);
   428	        memoryCache.rateLimitCounts.set(key, {
   429	            count: 0,
   430	            windowStart: now,
   431	            lastRequest: now
   432	        });
   433	    }
   434	
   435	    const counter = memoryCache.rateLimitCounts.get(key);
   436	    const windowDuration = limits.windowMs || 60000; // 默认1分钟窗口
   437	
   438	    // 取最大请求数：按 hourlyLimit → maxRequestsPerHour → maxRequests 优先级回退。
   439	    // 必须用显式判空而非 ||，否则配置值 0 会被当 falsy 跳过（这正是
   440	    // 「下发 maxRequests=0 却出现 100/小时」的根因）。
   441	    let maxRequests = pickLimitValue(
   442	        limits.hourlyLimit,
   443	        limits.maxRequestsPerHour,
   444	        limits.maxRequests // 兼容旧字段名
   445	    );
   446	
   447	    // 配置里没有任何限制字段 => 不限流。
   448	    // 这里过去兜底成硬编码 100，等于静默篡改本地端配置，已移除。
   449	    const isUnlimited =
   450	        maxRequests === undefined ||
   451	        maxRequests === null ||
   452	        maxRequests === -1 ||
   453	        maxRequests === 0; // 0 与 -1 同义，均表示无限制（与 UI 文案一致）
   454	
   455	    console.log(`   - 窗口持续时间: ${windowDuration}ms (${Math.round(windowDuration/1000)}秒)`);
   456	    console.log(`   - 最大请求数: ${isUnlimited ? '无限制' : maxRequests}`);
   457	    console.log(`   - 当前计数器: ${JSON.stringify(counter)}`);
   458	
   459	    // 检查是否需要重置窗口
   460	    const timeSinceWindowStart = now - counter.windowStart;
   461	    console.log(`   - 距离窗口开始时间: ${timeSinceWindowStart}ms`);
   462	
   463	    if (timeSinceWindowStart >= windowDuration) {
   464	        console.log(`   - 重置窗口 (超过${Math.round(windowDuration/1000)}秒)`);
   465	        counter.count = 0;
   466	        counter.windowStart = now;
   467	    }
   468	
   469	    // 增加计数
   470	    counter.count++;
   471	    counter.lastRequest = now;
   472	
   473	    console.log(`   - 更新后计数: ${counter.count}/${isUnlimited ? '无限制' : maxRequests}`);
   474	
   475	    // 累积IP统计数据（定期清理，防止内存泄漏）
   476	    if (!memoryCache.ipRequestStats[clientIP]) {
   477	        memoryCache.ipRequestStats[clientIP] = {
   478	            total_count: 0,
   479	            violations: 0,
   480	            paths: {},
   481	            lastAccess: now
   482	        };
   483	    }
   484	    memoryCache.ipRequestStats[clientIP].total_count++;
   485	    memoryCache.ipRequestStats[clientIP].lastAccess = now;
   486	
   487	    // 记录路径访问统计
   488	    const pathKey = uaType.includes('-path-') ? uaType.split('-path-')[1] : 'global';
   489	    if (!memoryCache.ipRequestStats[clientIP].paths[pathKey]) {
   490	        memoryCache.ipRequestStats[clientIP].paths[pathKey] = 0;
   491	    }
   492	    memoryCache.ipRequestStats[clientIP].paths[pathKey]++;
   493	
   494	    // 如果超限，记录违规
   495	    if (!isUnlimited && counter.count > maxRequests) {
   496	        memoryCache.ipRequestStats[clientIP].violations++;
