   511	        return {
   512	            allowed: false,
   513	            reason: `频率限制: ${counter.count}/${maxRequests} 在 ${Math.round(windowDuration/1000)}秒内`,
   514	            count: counter.count,
   515	            limit: maxRequests
   516	        };
   517	    }
   518	
   519	    return {
   520	        allowed: true,
   521	        count: counter.count,
   522	        limit: maxRequests
   523	    };
   524	}
