    48	    {
    49	        if (value is null) return;
    50	        if (value.Length > 128 * 1024) throw new ArgumentException("API 列表过长");
    51	        try
    52	        {
    53	            using var document = JsonDocument.Parse(value);
    54	            var root = document.RootElement;
    55	            if (root.ValueKind != JsonValueKind.Array || root.GetArrayLength() > 100)
    56	                throw new ArgumentException("API 配置必须是最多 100 项的数组");
    57	            foreach (var item in root.EnumerateArray())
