    66	                    : item.ValueKind == JsonValueKind.Object && item.TryGetProperty("url", out var address)
    67	                    && address.ValueKind == JsonValueKind.String ? address.GetString() : null;
    68	                if (!Uri.TryCreate(url, UriKind.Absolute, out var uri) || uri.Scheme is not ("http" or "https"))
