    if (e !== 'cancel' && e !== 'close') {
      error.value = `${e.message || '批量请求失败'}；请求中断时可能已有部分操作完成，请刷新核对后再重试。`
      emit('done')
    }
  } finally { busy.value = false; emit('busy', false) }
}
</script>
