import { onMounted, reactive, ref } from 'vue'
import { api } from './api.js'
const form = reactive({ enabled: false, baseUrl: '', serverType: 'generic', appId: '', appSecret: '', clearSecret: false })
const busy = ref(false), error = ref(''), notice = ref(''), hasSecret = ref(false)
async function load() {
  busy.value = true
  try { const data = await api.proxySettings(); Object.assign(form, data); hasSecret.value = data.hasSecret }
  catch (e) { error.value = e.message }
  finally { busy.value = false }
}
async function save() {
  busy.value = true; error.value = ''; notice.value = ''
  try {
    const data = await api.saveProxySettings(form)
    hasSecret.value = data.hasSecret; form.appSecret = ''; form.clearSecret = false
    notice.value = '配置已保存；请验证当前上游可用性。'
  } catch (e) { error.value = e.message }
  finally { busy.value = false }
}
async function verify() {
  busy.value = true; error.value = ''; notice.value = ''
  try { await api.validateProxy(); notice.value = '后端当前已保存的上游配置验证通过。' }
  catch (e) { error.value = e.message }
  finally { busy.value = false }
}
// 验证只使用后台已保存配置，不把草稿密钥发往普通用户验证接口。
onMounted(load)
</script>
